import test from 'node:test';import assert from 'node:assert/strict';import {bridgeHarness,fixtureReplyTurn} from './audit-bridge-harness.mjs';import {createOutboundTransport,knownOneBotRejection} from '../src/outbound-context.js';import {createPlugin} from '../plugins/qq-components/ctx-chat-reply-shape/index.js';import {describeSendRejection} from '../plugins/qq-components/ctx-chat-reply-shape/send-rejection.mjs';
const key='group:40001';
async function fixture(t,wording='send group message failed: 网络连接异常!'){let uncertain=true;const physical=[];const h=await bridgeHarness({config:{allow:{private:['123'],groups:['40001']},sendDelayMs:0},files:{'state/plugins/config/ctx-chat-reply-shape.json':{maxMessagesNormal:3,maxMessagesCasual:3,intervalMinMs:0,intervalMaxMs:0,longGapProbability:0}},globals:{fetch:async(url,opts)=>{if(String(url).endsWith('/send_group_msg')){physical.push(JSON.parse(opts.body));return {ok:true,status:200,json:async()=>uncertain?{status:'failed',retcode:1200,wording}:{status:'ok',retcode:0,data:{message_id:9000+physical.length}}};}return {ok:true,status:200,json:async()=>({status:'ok',retcode:0,data:[]})};}}});let server;t.after(async()=>{server?.closeAllConnections?.();if(server?.listening)await new Promise(r=>server.close(r));await h.close();});h.setMode('reserved2');h.appendSocialV2Message(key,'示例成员','[一张图片]','[一张图片]',false,false,'synthetic-image',[],'10001',[],undefined,false,{bodyComplete:true});await fixtureReplyTurn(h,key);const st=h.getSocialV2State(key);server=h.startConsoleServer();if(!server.listening)await new Promise(r=>server.once('listening',r));const headers={'content-type':'application/json','x-console-token':'fixture-console-token','x-agent-token':st.agentToken},base='http://127.0.0.1:'+server.address().port,call=async(route,body)=>{const r=await fetch(base+route,{headers:{...headers,...(body?.contentId?{'x-reply-content-id':body.contentId}:{})},...(body?{method:'POST',body:JSON.stringify({key,...body})}:{})});return {status:r.status,body:await r.json()};};await call('/api/socialV2/unread?key='+key);const d=await call('/api/socialV2/reply-contents',{groups:[{seqs:[1],kind:'chat'}]});assert.equal(d.body.ok,true);const contentId=d.body.contents[0].id;return {h,st,physical,contentId,call,allowSuccess:()=>uncertain=false,send:text=>call('/api/socialV2/send-message',{contentId,messages:text})};}

test('an ambiguous OneBot failed envelope cannot release a delivered image reply for a shortened retry',async t=>{const f=await fixture(t);const first=await f.send('这张图的蓝色节点是示例部分，旁边还有图例。');assert.equal(first.body.ok,false);assert.match(JSON.stringify(first.body),/delivery_unconfirmed/);assert(!f.st.recentMessages.find(m=>m.seq===1).repliedAt);const second=await f.send('这张图的蓝色节点是示例部分。');assert.equal(second.body.ok,false);assert.equal(f.physical.length,1,'unknown first send must not be physically repeated with the same prefix');await f.h.pluginHost.reload('ctx-chat-reply-shape');const third=await f.send('换一种说法再描述这张图。');assert.equal(third.body.ok,false);assert.equal(f.physical.length,1,'the uncertainty survives a component reload');const next=f.h.appendSocialV2Message(key,'示例成员','另一个独立问题','另一个独立问题',false,false,'synthetic-next',[],'10001',[],undefined,false,{bodyComplete:true});await f.call('/api/socialV2/unread?key='+key);const d=await f.call('/api/socialV2/reply-contents',{groups:[{seqs:[next.seq],kind:'chat'}]});assert.equal(d.body.ok,true);f.allowSuccess();const sent=await f.call('/api/socialV2/send-message',{contentId:d.body.contents[0].id,messages:'这是独立问题的回答。'});assert.equal(sent.body.sent,1,JSON.stringify(sent.body));assert.equal(f.physical.length,2);});

test('a definite pre-send rejection releases the reservation for a corrected request',async t=>{const f=await fixture(t,'invalid parameter');assert.equal((await f.send('先前的参数不正确。')).body.ok,false);f.allowSuccess();assert.equal((await f.send('参数已修正后的实际回复。')).body.sent,1);assert.equal(f.physical.length,2);});

test('unknown delivery blocks all rewrites and media for its content even with unused part allowance',async()=>{let state={},count=0;const ctx={config:{maxMessagesNormal:3,maxMessagesCasual:3,maxSendPerMinute:0,maxSendPerHour:0,intervalMinMs:0,intervalMaxMs:0,longGapProbability:0},state:{get:()=>state,set:p=>state={...state,...p}},callService:()=>null};let svc=createPlugin(ctx).services.replyPlan;const callService=(s,m,p)=>s==='replyPlan'?svc[m]?.(p):null;const transport=createOutboundTransport({callService,sleep:async()=>{}}),plan=svc.resolve({key,agent:true,turnId:'one',autonomousSource:{id:'image-one',kind:'proactiveCheck'},mood:{score:100},willingness:100}),context=transport.capture({key,envelope:{key,actionId:'one',reason:'proactiveCheck',replyPlan:plan},origin:'conversation',agent:true});await assert.rejects(transport.perform({key,context,text:'第一段图片回答',send:async()=>{count++;throw Error('socket timeout');}}));svc=createPlugin(ctx).services.replyPlan;for(const kind of ['text','image','poke'])await assert.rejects(transport.perform({key,context,kind,text:'第一段图片回答的改写',send:async()=>{count++;return {message_id:9};}}),/delivery_unconfirmed/);assert.equal(count,1);assert.equal(svc.progress({plan}).uncertain,1);assert.equal(svc.preview({key}).successful,0);});

test('uncertain delivery has terminal guidance without claiming successful delivery',()=>{const r=describeSendRejection('delivery_unconfirmed: send group message failed: 网络连接异常!');assert.equal(r?.code,'DELIVERY_UNCONFIRMED');assert.equal(r.retryable,false);assert.match(r.hint,/不.*重发/);});

test('failed status is not proof of rejection for transport and acknowledgement errors',()=>{for(const wording of ['网络连接异常!','socket timeout','connection reset','发送回执超时'])assert.equal(knownOneBotRejection({status:'failed',retcode:1200,wording}),false,wording);assert.equal(knownOneBotRejection({status:'failed',wording:'internal error'},503),false);assert.equal(knownOneBotRejection({status:'failed',wording:'invalid parameter'},400),true);});
